<div class="page-heading expense-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Expenses <span>&rsaquo;</span> <b>All Expenses</b></div><h1>Expenses</h1><p>Record and manage workshop expenses and supplier payments.</p></div><a class="btn btn-danger" href="index.php?page=admin&amp;section=expenses-add">+ New Expense</a></div>
<div class="row g-3 expense-summary"><div class="col-sm-6 col-xl-3"><div class="stat-card expense-card-green"><small>Total Expenses (All Time)</small><strong>Rs. <?= number_format($summary['total'],2) ?></strong><span>All time</span></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card expense-card-blue"><small>This Month</small><strong>Rs. <?= number_format($summary['month'],2) ?></strong><span><?= date('M Y') ?></span></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card expense-card-orange"><small>This Week</small><strong>Rs. <?= number_format($summary['week'],2) ?></strong><span>Current week</span></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card expense-card-red"><small>Pending Payments</small><strong>Rs. <?= number_format($summary['pending'],2) ?></strong><span>Balance remaining</span></div></div></div>
<div class="admin-panel expense-filters"><form class="expense-filter-bar" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="expenses"><label>Search<input class="form-control" name="search" value="<?= e($filters['search']) ?>" placeholder="Search expense, supplier, description..."></label><label>Date From<input class="form-control" type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>Date To<input class="form-control" type="date" name="to" value="<?= e($filters['to']) ?>"></label><label>Status<select class="form-select" name="status"><option value="">All Status</option><?php foreach($labels as $value=>$label): ?><option value="<?= e($value) ?>" <?= $filters['status']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><div class="expense-filter-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=expenses">Reset</a><button class="btn btn-danger">Filter</button></div></form></div>
<div class="admin-panel expense-list"><div class="panel-heading"><h2>Expense List</h2><span class="text-muted"><?= count($rows) ?> records</span></div><div class="table-responsive"><table class="table admin-table expense-table"><thead><tr><th>Expense No.</th><th>Date</th><th>Category</th><th>Description</th><th>Supplier / Vendor</th><th>Payment</th><th>Total (Rs.)</th><th>Paid</th><th>Balance</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="11" class="empty-table">No expenses found. Click New Expense to add one.</td></tr><?php else: foreach($rows as $row): ?><tr><td><strong class="expense-number"><?= e($row['expense_no']) ?></strong></td><td><?= e($row['expense_date']) ?></td><td><?= e($row['category']) ?></td><td><?= e($row['description']) ?></td><td><?= e($row['supplier_name']?:'No supplier') ?></td><td><?= e(ucfirst($row['payment_method'])) ?></td><td><strong><?= number_format((float)$row['total_amount'],2) ?></strong></td><td><?= number_format((float)$row['paid_amount'],2) ?></td><td><?= number_format((float)$row['balance_amount'],2) ?></td><td><span class="expense-status expense-status-<?= e($row['status']) ?>"><?= e($labels[$row['status']]??$row['status']) ?></span></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=expenses-view&amp;id=<?= (int)$row['id'] ?>" title="View">&#128065;</a><a href="index.php?page=admin&amp;section=expenses-edit&amp;id=<?= (int)$row['id'] ?>" title="Edit">&#9998;</a><form method="post" action="index.php?page=admin&amp;section=expenses-delete" onsubmit="return confirm('Cancel this expense?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="expense_id" value="<?= (int)$row['id'] ?>"><button title="Cancel">&#128465;</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
